package cl.dynasty.nexusbeacon.platform.classic;
import java.lang.reflect.Method;import org.bukkit.Server;import org.bukkit.entity.Player;import org.bukkit.plugin.Plugin;import org.bukkit.plugin.RegisteredServiceProvider;
final class ClassicVaultEconomyService implements ClassicEconomyService {private final Plugin plugin;private String diagnostic="Vault unavailable";ClassicVaultEconomyService(Plugin plugin){this.plugin=plugin;}public boolean isAvailable(){return provider()!=null;}public String diagnostic(){return diagnostic;}public boolean has(Player p,double amount){Object provider=provider();return provider!=null&&Boolean.TRUE.equals(invoke(provider,"has",p,amount));}public boolean withdraw(Player p,double amount){Object provider=provider();return provider!=null&&success(invoke(provider,"withdrawPlayer",p,amount));}public boolean deposit(Player p,double amount){Object provider=provider();return provider!=null&&success(invoke(provider,"depositPlayer",p,amount));}private Object provider(){try{Server server=plugin.getServer();Plugin vault=server.getPluginManager().getPlugin("Vault");if(vault==null||!vault.isEnabled()){diagnostic="Vault unavailable";return null;}Class<?> economy=Class.forName("net.milkbowl.vault.economy.Economy",false,vault.getClass().getClassLoader());RegisteredServiceProvider<?> registration=server.getServicesManager().getRegistration(economy);if(registration==null||registration.getProvider()==null){diagnostic="Vault has no economy provider";return null;}diagnostic="available";return registration.getProvider();}catch(Throwable failure){diagnostic="Vault resolution failed: "+failure.getClass().getSimpleName();return null;}}private Object invoke(Object target,String name,Player player,double amount){try{Method method=target.getClass().getMethod(name,org.bukkit.OfflinePlayer.class,double.class);return method.invoke(target,player,Double.valueOf(amount));}catch(Throwable failure){diagnostic="Vault operation failed: "+failure.getClass().getSimpleName();return null;}}private boolean success(Object response){if(response==null)return false;try{return Boolean.TRUE.equals(response.getClass().getMethod("transactionSuccess").invoke(response));}catch(Throwable failure){diagnostic="Vault response failed";return false;}}}
